    mov.u32 %r4, %ctaid.y;
    mov.u32 %r12, %ctaid.x;
    mov.u32 %r5, %ntid.x;
    // ROWS=2 row tile owned by this CTA; ctaid.y is a row-tile index.
    shl.b32 %r17, %r4, 1;
    setp.ge.u32 %p1, %r17, %r1;
    @%p1 bra DONE;
