    fma.rn.f32 %f1, %f6,  %f10, %f1;
    fma.rn.f32 %f1, %f7,  %f11, %f1;
    fma.rn.f32 %f1, %f8,  %f12, %f1;
    fma.rn.f32 %f1, %f21, %f17, %f1;
    fma.rn.f32 %f1, %f22, %f18, %f1;
    fma.rn.f32 %f1, %f23, %f19, %f1;
    fma.rn.f32 %f1, %f24, %f20, %f1;
    fma.rn.f32 %f2, %f13, %f9,  %f2;
    fma.rn.f32 %f2, %f14, %f10, %f2;
    fma.rn.f32 %f2, %f15, %f11, %f2;
    fma.rn.f32 %f2, %f16, %f12, %f2;
    fma.rn.f32 %f2, %f25, %f17, %f2;
    fma.rn.f32 %f2, %f26, %f18, %f2;
    fma.rn.f32 %f2, %f27, %f19, %f2;
    fma.rn.f32 %f2, %f28, %f20, %f2;
