    ld.global.L2::cache_hint.v4.f32 {%f9, %f10, %f11, %f12}, [%rd6], %rd9;
    ld.global.cs.v4.f32 {%f5, %f6, %f7, %f8}, [%rd7];
    ld.global.cs.v4.f32 {%f13, %f14, %f15, %f16}, [%rd8];
