    mov.b32 %r22, %f2;
    shfl.sync.down.b32 %r23, %r21, 16, 0x1f, 0xffffffff;
    mov.b32 %f25, %r23;
    add.f32 %f1, %f1, %f25;
    shfl.sync.down.b32 %r23, %r22, 16, 0x1f, 0xffffffff;
    mov.b32 %f26, %r23;
    add.f32 %f2, %f2, %f26;
    mov.b32 %r21, %f1;
    mov.b32 %r22, %f2;
    shfl.sync.down.b32 %r23, %r21, 8, 0x1f, 0xffffffff;
    mov.b32 %f25, %r23;
    add.f32 %f1, %f1, %f25;
    shfl.sync.down.b32 %r23, %r22, 8, 0x1f, 0xffffffff;
    mov.b32 %f26, %r23;
    add.f32 %f2, %f2, %f26;
    mov.b32 %r21, %f1;
    mov.b32 %r22, %f2;
    shfl.sync.down.b32 %r23, %r21, 4, 0x1f, 0xffffffff;
    mov.b32 %f25, %r23;
    add.f32 %f1, %f1, %f25;
    shfl.sync.down.b32 %r23, %r22, 4, 0x1f, 0xffffffff;
    mov.b32 %f26, %r23;
    add.f32 %f2, %f2, %f26;
    mov.b32 %r21, %f1;
    mov.b32 %r22, %f2;
    shfl.sync.down.b32 %r23, %r21, 2, 0x1f, 0xffffffff;
    mov.b32 %f25, %r23;
    add.f32 %f1, %f1, %f25;
    shfl.sync.down.b32 %r23, %r22, 2, 0x1f, 0xffffffff;
    mov.b32 %f26, %r23;
    add.f32 %f2, %f2, %f26;
    mov.b32 %r21, %f1;
    mov.b32 %r22, %f2;
    shfl.sync.down.b32 %r23, %r21, 1, 0x1f, 0xffffffff;
    mov.b32 %f25, %r23;
    add.f32 %f1, %f1, %f25;
    shfl.sync.down.b32 %r23, %r22, 1, 0x1f, 0xffffffff;
    mov.b32 %f26, %r23;
    add.f32 %f2, %f2, %f26;
