    shr.u32 %r25, %r3, 5;
    shl.b32 %r26, %r25, 2;
    cvt.u64.u32 %rd19, %r26;
    add.u64 %rd19, %rd19, %rd18;
    @%p1 st.shared.f32 [%rd19], %f1;
    add.u64 %rd20, %rd19, 16;
    @%p1 st.shared.f32 [%rd20], %f2;
