    ld.shared.f32 %f26, [%rd24+4];
    add.f32 %f25, %f25, %f26;
    ld.shared.f32 %f26, [%rd24+8];
    add.f32 %f25, %f25, %f26;
    ld.shared.f32 %f26, [%rd24+12];
