    ld.shared.f32 %f26, [%rd24+20];
    add.f32 %f25, %f25, %f26;
    ld.shared.f32 %f26, [%rd24+24];
    add.f32 %f25, %f25, %f26;
    ld.shared.f32 %f26, [%rd24+28];
    add.f32 %f25, %f25, %f26;
